<div class="topbar"><h1><?=e($title)?></h1></div><form class="card" method="post" action="<?=url($isNew?'/admin/'.$slug:'/admin/'.$slug.'/'.$doc['id'])?>"><?=csrf_field()?><div class="form-grid"><label>Customer<select name="customer_id" required><?php foreach($customers as $c):?><option value="<?=$c['id']?>" <?=($doc['customer_id']??0)==$c['id']?'selected':''?>><?=e($c['code'].' · '.$c['company_name'])?></option><?php endforeach;?></select></label><label>Currency<select name="currency"><?php foreach(Money::CURRENCIES as $c=>$v):?><option <?=($doc['currency']??'AED')===$c?'selected':''?>><?=$c?></option><?php endforeach;?></select></label><label>Issue date<input type="date" name="issue_date" value="<?=e($doc['issue_date']??'')?>"></label><label>Due/valid until<input type="date" name="<?= $type==='quotation'?'valid_until':'due_date' ?>" value="<?=e($doc['valid_until']??$doc['due_date']??'')?>"></label><label>Discount<input name="discount" value="<?=e($doc['discount']??'0.00')?>"></label><label>Tax %<input name="tax_rate" value="<?=e($doc['tax_rate']??'0.00')?>"></label></div><h3>Lines</h3><div id="lines"><?php foreach($lines as $l):?><div class="form-grid"><input name="line_sku[]" placeholder="SKU" value="<?=e($l['sku']??'')?>"><input name="line_description[]" placeholder="Description" required value="<?=e($l['description']??'')?>"><input name="line_qty[]" placeholder="Qty" value="<?=e($l['qty']??'1')?>"><input name="line_unit_price[]" placeholder="Unit price" value="<?=e($l['unit_price']??'0')?>"></div><?php endforeach;?></div><label>Notes<textarea name="notes"><?=e($doc['notes']??'')?></textarea></label><button class="btn btn-primary">Save</button></form>
